import datetime
import re
from dataclasses import dataclass
from decimal import ROUND_HALF_EVEN, Decimal, localcontext
from typing import Callable, Dict, Iterable, List

__all__ = [
    "Entry",
    "ParseError",
    "parse",
    "balance",
    "by_category",
    "by_month",
    "format_amount",
]

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_FIELD_SEP = re.compile(r"[ \t]+")


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


class ParseError(ValueError):
    """A ledger line is invalid. ``line`` is the 1-based physical line number."""

    def __init__(self, line: int, message: str) -> None:
        super().__init__(line, message)
        self.line = line
        self.message = message

    def __str__(self) -> str:
        return "line %d: %s" % (self.line, self.message)


def _parse_line(number: int, line: str) -> Entry:
    fields = _FIELD_SEP.split(line.strip(" \t"), 3)
    if len(fields) < 3:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_text, category, amount_text = fields[0], fields[1], fields[2]
    note = fields[3].strip() if len(fields) > 3 else ""

    if not _DATE_RE.fullmatch(date_text):
        raise ParseError(number, "invalid date %r" % date_text)
    try:
        date = datetime.date(
            int(date_text[0:4]), int(date_text[5:7]), int(date_text[8:10])
        )
    except ValueError:
        raise ParseError(number, "invalid date %r" % date_text) from None

    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(number, "invalid amount %r" % amount_text)

    return Entry(date, category.lower(), Decimal(amount_text), note)


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order."""
    entries = []
    for number, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(_parse_line(number, line))
    return entries


def balance(entries: Iterable[Entry]) -> Decimal:
    """Total of all amounts (``Decimal(0)`` for no entries)."""
    return sum((e.amount for e in entries), Decimal(0))


def _group(entries: Iterable[Entry], key: Callable[[Entry], str]) -> Dict[str, Decimal]:
    totals: Dict[str, Decimal] = {}
    for entry in entries:
        k = key(entry)
        totals[k] = totals.get(k, Decimal(0)) + entry.amount
    return totals


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per lower-case category, keys in order of first appearance."""
    return _group(entries, lambda e: e.category)


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per ``YYYY-MM``, keys in order of first appearance."""
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


